const flaw="[풀이] f(x)=x² 의 2에서 미분계수. ①f(2 +h)−f(2)=4h +h² ②이를 h로 나누면 4h +h이다. ③h →0에서 0이다.";
lessons.push(concept({id:'C6',course:'calc',unit:'diff',title:"평균 변화율에서 미분계수로",standards:['12미적Ⅰ-02-01'],prereqs:['C2','B3'],goals:["차분몫의입력간격을읽고할선의기울기극한과함숫 값을 구별한다"],misconceptions:[{id:'C6-M1',claim:"미분계수는 그 점의 높이다",repair:"미분계수는 출력 차/ 입력 차의 극한인 기울기다.",bridge:'B3'},{id:'C6-M2',claim:"차분몫에 h=0을 처음부터 넣는다",repair:"h ≠0인 주변에서 정리한 뒤 h →0의 극한을 구한다.",bridge:'C2'},{id:'C6-M3',claim:"입력 변화가 2 h여도분모h면 같은 미분계수다",repair:"실제 간격 2h로 맞추면 바깥에 2 배가 남는다.",bridge:'C1'}],prediction:"f(2)가 4이면 f ′(2)도 항상 4일까? 점의 높이를 바꾸면 기울기도 반드시 바뀔까?",why:["평균 변화율은 입력이 얼마 변할 때 출력이 얼마 변하는지 한 단위로 환산한 값이다. 그래프에서는 두 점을 잇는 할 선의 기울기다. 순간의 변화는 두 번째 점을 첫 번째 점에 가깝게 움직일 때 기울기가 어느 한 값에 가까워지는지로 정의한다. 이 극한이 유한하게 존재하면 그 값이 미분계수다.","한 점의 출력과 변화율은 서로 다른 정보다. 전체 그래프를 위로 이동해도 출력 차는 같으므로 기울기는 유지된다. 차분몫에서는 분자의 입력 변화와 분모의 간격을 정확히 맞춰야한다. h를 바로 0으로 놓아0/0을 계산하려하지 말고 h가 0이 아닌 주변에서 약분할 수 있는 식을 먼저 찾는다. 수치할 선의 관찰은 정의의 이해를 돕지만 일반 계산의 근거는 극한이다."],derivation:[{title:"두 점의 기울기",body:"a와 a +h에서 평균 변화율은[f(a +h)−f(a)]/h이며 h ≠0이다."},{title:"극한 정의",body:"h를 양쪽에서 0으로 보낼 때 같은 유한 값에 접근하면 f ′(a)라 쓴다."},{title:"간격의 배율",body:"[f(a +2h)−f(a)]/h=2·[f(a +2h)−f(a)]/(2h)이므로 미분가능할 때 극한은 2f ′(a)다."}],formula:"$f'(a)=\\lim_{h\\to0}\\frac{f(a+h)-f(a)}h\\quad(h\\ne0\\text{인 주변에서 계산})$",conditions:[{require:"평균 변화율의 분모는 실제 입력 차",ifMissing:"배율이 빠지거나 부호가 달라진다",example:"f(a +2h)와 f(a)를 빼면서 h로 나누면 미분계수의 2 배다."},{require:"미분계수는 양쪽의 같은 유한 극한",ifMissing:"한 방향할 선만 보고 미분가능이라고 쓴다",example:"|x |의 0 좌우 기울기는 −1,1로 다르다."}],representation:{kind:'secant',controls:[control('x',"기준 입력 a",-1,2,.5,1),control('h',"입력 간격 h",.05,1,.05,.5)],task:"f(x)=x² 의 할선에서 h를 줄이며 평균 기울기와 현재 미분계수 2a를 비교한다.",readBack:"그래프의 높이 a²와 기울기 2a가 언제 같고 언제 다른가? 우연히 같은 점이 정의를 같게 만들까?",caption:"현재 할 선 기울기는 2a +h다. 수치 접근과 극한 값을 구별한다."},example:{prompt:"정의로 f(x)=x² 의 f ′(2)를 구하라.",steps:[{title:"출력 차",body:"(2 +h)² −4=4h +h²다."},{title:"간격으로 나누기",body:"h ≠0에서 차분 몫은 4 +h다."},{title:"극한",body:"h →0에서 4로 가므로 f ′(2)=4다."}],answer:'4'},faded:numberQ('faded',"f(x)=x² 의 1에서 차분 몫은 2 +h다. f ′(1)은?",2,"h →0의 극한은 2다.","평균 기울기의 극한을 본다.",1,"함숫값f(1)과 기울기를 혼동했다."),entry:[numberQ('entry',"두 점(1,2),(3,8)의 할 선 기울기는?",3,"출력 차 6/ 입력 차 2=3다.","Δy/ Δx다."),numberQ('entry',"h ≠0에서(4h +h²)/h=4 +h다. h →0 극한은?",4,"4 +h가 4로 접근한다.","약분 후 극한을 읽는다.")],checks:[numberQ('basic',"정의로 구한 x² 의 3에서 미분계수는?",6,"차분 몫 6 +h의 극한 6다.","높이 9와 구별한다.",9,"함숫 값을 기울기로 썼다."),numberQ('basic',"lim(h →0)[f(2 +h)−f(2)]/h=5다. f ′(2)는?",5,"미분계수의 정의 그대로다.","표기의 의미를 읽는다.",2,"입력 위치를 변화율로 답했다."),numberQ('transfer',"f ′(a)=3이다. lim(h →0)[f(a +2h)−f(a)]/h는?",6,"실제 간격 2h로 맞추면 2f ′(a)=6이다.","분모를 실제 입력 차로 맞춘다.",3,"간격 배율 2를 빠뜨렸다.",'M3'),numberQ('transfer',"점(2,7)에서 할 선 기울기의 양쪽 접근 값이 모두 −3이다. f ′(2)는?",-3,"높이 7이 아닌 기울기 극한 −3이다.","점의 좌표와 기울기 정보를 나눠 읽는다.",7,"그래프 높이를 미분계수로 썼다."),...errorSet(flaw,['②','①',"③에서만"],["4h를 h로 나누면 4이지 4h가 아니다.","출력 차 전개는 맞다.","잘못된 나눗셈이 먼저다."],["분자의 모든 항을 h로 나눠야한다","h는 처음부터 0이어야한다","기울기는 언제나 0이다"],["4h/h=4,h²/h=h다.","주변에서는 h ≠0이다.","x²의 기울기는 위치에 따라 달라진다."],numberQ('repair',"고친 f ′(2)의 값은?",4,"차분 몫 4 +h의 극한 4다.","h ≠0에서 약 분한다.",0,"잘못된 h 인수를 남겼다.",'M2'),"평균 변화율 식을 항별로 나눈다."),pickQ('explanation',"“f(a)를 먼저 계산해 상수가 됐으므로 f ′(a)=0이다.”의 판정은?", ["결함 있음: 입력 변화에 따른 출력 차를 봐야한다","옳음: 한 점의 값은 상수라 모든 미분계수 0이다","결함 있음: 상수 함수의 미분계수도 항상 1이다"],["f(a +h)를 함께 보는 극한 정의가 필요하다.","한 점 값만 남겨 변화 정보를 지웠다.","상수 함수의 출력 차는 0이다."],"입력 전체의 함수와 특정 점 값을 구별한다.",['M1','M1'])],explanation:{prompt:"미분계수를 높이가 아닌 기울기의 극한으로 설명하자.",claims:["두 출력의 차","실제 입력 간격","양쪽 유한 극한"],model:"기준점과 가까운 점의 출력 차를 입력 차로 나눠 평균 기울기를 만든다. 간격을 0으로 보낼 때 양쪽에서 같은 유한 값으로 가면 그 값이 기준 점의 미분계수다."}}));
